"""Vulkan-first feature research; capability declarations are not execution receipts."""

BASE = 'https://docs.vulkan.org/refpages/latest/refpages/source/'
SOURCES = [
 ('S70', 'VK_NV_cluster_acceleration_structure', 'Revision4 specifies CLAS, cluster BLAS and indirect build/move operations. Depends on KHR acceleration structures; query the cluster feature, geometry limits and alignment properties. No Basix CLAS execution result follows.'),
 ('S71', 'VK_NV_cooperative_matrix2', 'Builds on KHR cooperative matrix with independently gated flexible dimensions, workgroup scope, conversions, reductions, per-element operations, tensor addressing and block loads. Enumerate dimensions/types and shared-memory limits.'),
 ('S72', 'VK_NV_cooperative_vector', 'Per-invocation vectors support small matrix-vector inference. Cooperative-vector inference and training are separate features. Enumerate type tuples, stages and component limits; optimized matrix layouts require conversion.'),
 ('S73', 'VK_EXT_ray_tracing_invocation_reorder', 'Ratified revision2, modified2026-04-02; successor to NV invocation reorder. Requires KHR ray-tracing pipelines, its feature and shader/compiler support. Query reordering hint and shader-binding-table record limit.'),
 ('S74', 'VK_NV_ray_tracing_linear_swept_spheres', 'Independent spheres and linearSweptSpheres features add dedicated geometry and pipeline requirements. Requires KHR ray-tracing pipelines. Hardware acceleration and performance on the named adapter remain untested.'),
 ('S75', 'VK_NV_partitioned_acceleration_structure', 'Partitioned instance structures support localized updates and partition translations. Requires KHR acceleration structures, its feature and maxPartitionCount query, dedicated build operations and descriptor integration.'),
 ('S76', 'VK_EXT_device_generated_commands', 'Ratified multi-vendor DGC route with feature and stage/binding/sequence/token limits. Requires BDA plus extended-flags or maintenance5, or Vulkan1.3. Preprocessing and synchronization remain application responsibilities.'),
 ('S77', 'VK_NV_device_generated_commands_compute', 'Older NV compute route depends on NV device-generated commands; compute, indirect-pipeline and capture-replay features are separate. EXT DGC is a separate integration, not a symbol rename.'),
 ('S78', 'VK_KHR_compute_shader_derivatives', 'Portable successor to NV compute derivatives. Quad and linear derivative grouping are separate features. Invocation grouping must match the execution mode; arbitrary divergent ray neighborhoods do not define useful texture footprints.'),
 ('S79', 'VK_EXT_memory_decompression', 'Ratified successor to NV memory decompression. Query feature, supported methods and indirect-count limit. Current method is GDeflate1.0; dedicated EXT usage/stage/access bits apply. Not a general texture or geometry decoder.'),
 ('S80', 'VK_EXT_opacity_micromap', 'Ratified EXT opacity micromaps encode subtriangle opacity to reduce alpha traversal work. Requires acceleration structures plus synchronization2 or Vulkan1.3. Query micromap feature and subdivision limits; preserve unknown-opacity behavior.'),
 ('S81', 'VK_KHR_opacity_micromap', 'Ratified successor modified2026-05-08 requires KHR device-address commands and acceleration structures. Uses AS-backed micromaps. Ray-query shaders declare OpacityMicromapIdKHR execution mode; ray pipelines require the OMM flag. Not a drop-in EXT alias.'),
 ('S82', 'VK_AMDX_shader_enqueue', 'Revision2 remains provisional and explicitly discouraged for production. Compute shaders enqueue compute/mesh work through execution graphs. AMDX is not NV; NVIDIA support was not established. Graph/scratch/dependency constraints apply.'),
 ('S83', 'VK_KHR_cooperative_matrix', 'Portable cooperative-matrix baseline with enumerated supported type/dimension/scope combinations and feature gates. NV matrix2 adds capabilities beyond this contract; cooperative vectors are a distinct execution abstraction.'),
]


def apply(sections, sources, source, section, table, cite):
    for sid, name, note in SOURCES:
        source(sid, name, BASE + name + '.html', note,
               rights='Official specification linked with original summary; specification prose CC-BY-4.0. No implementation or sample code copied.')
    source('S84', 'Vulkan-Docs licensing', 'https://github.com/KhronosGroup/Vulkan-Docs/blob/main/LICENSE.adoc',
           'Specification source documents use CC-BY-4.0; scripts/XML and other files have their own SPDX terms. Research prose and implementation dependencies must be tracked separately.',
           rights='License metadata linked and summarized; no specification text redistributed.')
    source('S85', 'Vulkan generated header and license', 'https://github.com/KhronosGroup/Vulkan-Headers/blob/main/include/vulkan/vulkan_core.h',
           'Current generated header carries Apache-2.0 OR MIT. Latest registry declarations do not establish driver implementation or compatibility with the engine\'s pinned headers/compiler.',
           rights='Apache-2.0 OR MIT in the linked generated header. Select and retain applicable notices for adopted files.')
    by = {s['id']: s for s in sections}
    by['summary']['body'] += '<p><strong>Vulkan-first research:</strong> compare techniques across APIs while retaining native contracts and independent feature gates. Latest standardized replacements are research, not newly measured engine features. <a href="#vulkan-features">Vulkan feature adoption map</a>.</p>' + cite('S70', 'S71', 'S81')
    section('vulkan-features', 'Vulkan-first features: native contracts and adoption gates', '''
<p>Basix currently uses NoGraphicsAPI with a native Vulkan adapter for hardware rays and SDK interoperability. New extension entry points, feature chains, native resource/descriptor metadata and retirement rules need explicit adapters. A native Vulkan feature is not automatically exposed by NoGraphicsAPI's public interface.</p>
<div class="callout"><strong>Four different facts</strong><p><b>Enumerated:</b> extension name reported. <b>Enabled:</b> required feature bits enabled after querying support and numeric properties before device creation. <b>Oracle-tested:</b> actual operation matches an independent reference under validation, including negative controls and lifetime cleanup. <b>Performance-measured:</b> comparable workloads establish time, memory and quality costs. Record each separately; none implies the next.</p></div>
<p>This research adds no extension execution or timing measurements. The named RTX4090/NVIDIA617.42 configuration and ordinary BLAS/TLAS/ray-query results do not prove CLAS, SER, partitioned AS, matrix2, vectors or micromap paths. The later capability receipt adds feature/property queries, but no advanced-extension execution. Pinned headers1.4.357/compiler support must be checked independently; newer ratified replacements below are research comparisons, not compiled engine support.</p>
<h3>Same technique family, different contracts</h3>''' + table(
        ['Technique', 'DirectX research path', 'Vulkan candidate / boundary'], [
            ('Shader linear algebra / inference', 'DX12 LinAlg; compiler/runtime capabilities remain separate gates.', 'KHR cooperative matrix supplies a portable matrix baseline; NV cooperative_matrix2 adds flexible/workgroup/tensor operations; NV cooperative_vector suits per-invocation MLPs. No source, layout or execution-contract interchangeability.'),
            ('Cluster geometry / dynamic detail', 'DXR2 CLAS/cluster-BLAS specification and SDK/driver gates.', 'NV cluster_acceleration_structure offers CLAS/cluster-BLAS operations today as a vendor contract. Not standardized DXR2 support or the same binary/API contract.'),
            ('Scene partitioning', 'DXR2 partitioned-TLAS research.', 'NV partitioned_acceleration_structure is an independent structure/descriptor/build contract. Conventional update-capable TLAS remains the baseline.'),
            ('GPU work selection', 'Released Work Graphs versus later Work Lists research.', 'EXT DGC selects generated commands; AMDX shader enqueue is provisional execution graphs. Neither name establishes equivalent scheduling semantics or NVIDIA support.'),
        ]) + cite('S32', 'S38', 'S45', 'S70', 'S71', 'S72', 'S75', 'S76', 'S82', 'S83') + '''
<h3>Adoption priorities</h3>''' + table(
        ['Feature / priority', 'Required contract and limits', 'Next independent test / fallback'], [
            ('Compute derivatives · material correctness first', 'Prefer KHR over NV; computeDerivativeGroupQuads / computeDerivativeGroupLinear and valid invocation grouping.', 'Compare coherent texture footprints against explicit gradients/LOD. Divergent PT needs ray cones/differentials or explicit LOD; ordinary lane differences alone are insufficient.'),
            ('Opacity micromaps · high after alpha baseline', 'EXT micromap + AS/sync gates; newer KHR changes objects, dependencies and shader requirements. Query subdivision limits.', 'Alpha-cutoff/UV/boundary oracle against ordinary candidate-alpha evaluation; unknown opacity falls back. Dynamic textures need an invalidation policy. Separate EXT/KHR adapters.'),
            ('NV cluster AS · high geometry research', 'clusterAccelerationStructure; KHR AS; maxVerticesPerCluster, maxTrianglesPerCluster, maxClusterGeometryIndex and five alignment properties.', 'Identical ordinary-BLAS versus CLAS/cluster-BLAS rays, then rebuild/move/deformation/lifetime tests. Measure build, traversal and scratch/AS memory at equal geometry.'),
            ('EXT/NV invocation reorder · later PT', 'KHR ray-tracing pipeline; rayTracingInvocationReorder; query reorder hint and EXT SBT limit; compiler/hit-object support.', 'Prefer EXT when supported. Compare pipeline PT with/without reorder on identical rays/materials. Existing compute ray queries are not SER. Retain ordinary pipeline/wavefront baseline.'),
            ('NV partitioned AS · later large worlds', 'partitionedAccelerationStructure, maxPartitionCount; dedicated descriptor/build/partition rules.', 'Compare localized moving partitions with ordinary update-capable TLAS; test translations and lifetime. Do not describe every conventional TLAS update as a full rebuild.'),
            ('NV cooperative_matrix2 · optional neural compute', 'Requires KHR cooperative_matrix. Gate workgroup scope, flexible dimensions, reductions, conversions, per-element, tensor addressing and block loads individually.', 'Enumerate type/dimension/scope combinations; compare scalar/KHR/NV output precision, occupancy and shared-memory costs. Keep scalar/KHR subset fallback.'),
            ('NV cooperative_vector · optional neural materials', 'cooperativeVector; separate cooperativeVectorTraining. Query stages, type tuples, max components and matrix conversions.', 'Small fixed MLP against independent scalar inference; test layout conversion and precision. Training and optimized-layout portability are separate claims.'),
            ('NV spheres / linear swept spheres · hair research', 'Separate spheres / linearSweptSpheres bits; KHR ray-tracing pipeline; radius-buffer format and pipeline flags.', 'Analytic sphere/curve intersection oracle, endcaps/radii and shading. Keep tessellated or procedural-AABB fallback; RTX4090 hardware speed unmeasured.'),
            ('EXT DGC / older NV compute DGC · later dispatch', 'Prefer ratified EXT if supported. Query stage/binding/sequence/token/stride limits; preprocessing and explicit synchronization.', 'Generated dispatch versus ordinary indirect compute, including count overflow and pipeline compatibility. NV compute needs its own NV DGC dependencies; no Work Graphs equivalence.'),
            ('EXT/NV decompression · later streaming', 'memoryDecompression; decompressionMethods / maxDecompressionIndirectCount; GDeflate1.0 and dedicated EXT scopes.', 'Decoded bytes versus CPU oracle, sizes and barriers. Keep CPU/compute decoder. Does not decode BC textures, neural weights or DGF automatically.'),
            ('AMDX shader enqueue · deferred experiment', 'Provisional, not production-ready; shaderEnqueue / shaderMeshEnqueue, graph/scratch limits and maintenance5/pipeline-library dependencies.', 'No NV extension or NVIDIA support established. Retain explicit compute work queues/indirect dispatch; do not block current renderer.'),
        ]) + cite(*[s[0] for s in SOURCES]) + '''
<p><strong>Capability receipt contract:</strong> record adapter model, driver, loader/API version, header/compiler revisions, extension names, queried/enabled feature bits and numeric properties. Compile the actual shader capabilities, then execute build/dispatch/trace/readback and cleanup under validation. Test descriptor-heap/pointer-root compatibility explicitly instead of assuming descriptor-set samples transfer unchanged. Preserve failed controls and narrow successful scopes in the roadmap logbook.</p>
<p><strong>Research and code licenses:</strong> these are original summaries linked to official specifications. Vulkan-Docs prose is CC-BY-4.0; selected registry/tool files have separate SPDX terms. Generated Vulkan headers offer Apache-2.0 OR MIT, permitting an MIT selection with retained notices. An extension specification does not license vendor SDKs, models, samples or assets; audit chosen files/revisions separately.</p>''' + cite('S84', 'S85'))


def enrich_library(library):
    library['summary'].append('Vulkan-first adoption map separates native extension contracts, portable replacements and enumeration/enabling/oracle/performance evidence; no advanced-extension execution measurements added.')
    library['findings'].append(dict(
        id='F17', title='Vulkan technique counterparts require independent native contracts',
        question_ids=['Q2', 'Q8'], topic='rendering',
        claim='KHR cooperative matrix/NV matrix2/vector and NV cluster AS address related technique families to DirectX LinAlg/DXR2, but APIs, layouts, shader semantics and runtime capability contracts are not interchangeable.',
        evidence_type='primary documentation synthesis', confidence='high',
        context='Official Khronos registry/refpages checked2026-10-28; implementation remains pinned separately.',
        strengths='Primary feature/dependency/property declarations and explicit distinction between NV, KHR, EXT and provisional AMDX routes.',
        limitations='Mutable latest specifications; this source synthesis supplies no shader execution oracle or performance benchmark; the separate Basix receipt records queries only. Pinned headers/compiler may lack latest replacements.',
        implications='Preserve ordinary ray/compute fallbacks, implement native adapters and advance each feature only through separately recorded enumeration, enablement, correctness and performance gates.',
        tags=['Vulkan', 'cluster geometry', 'linear algebra', 'native interop', 'roadmap'],
        evidence=[dict(source_id=s, locator='Extension dependencies, feature/property declarations and descriptions', relation='supports', note='Research contract only; no Basix execution claim.') for s in ['S70', 'S71', 'S72', 'S76', 'S81', 'S83']]))
    library['scope_changes'].append('Added Vulkan-first feature chapter and technique mapping; latest KHR/EXT comparisons remain research, with no new implementation status promotion.')
    library['search_log'].append(dict(date='2026-10-28', phase='targeted extension research', engine='Official Khronos registry and Vulkan refpages', query='NV cluster matrix2 vector SER partitioned AS DGC derivatives decompression micromap shader enqueue', source_ids=[s[0] for s in SOURCES] + ['S84', 'S85'], outcome='Prioritized optional native adapters, portable replacements and explicit feature/property/oracle/performance gates; provisional AMDX enqueue deferred.'))
